    def is_prime(x):
        '''Check if the number x is prime'''
        for i in range(2, int(x ** 0.5) + 1):
            if x % i == 0:
                return False
        return True

    if is_prime(n):
        def count_twin_primes(pairs: List[tuple]) -> int:
            '''
            Util function for non-prime scenarios, public only due to search requirements
            '''
            count = 0
            smallest = None
            for pair in pairs:
                if (pair[0] < smallest and is_prime(pair[0] + 2)) or (pair[0] > smallest and is_prime(pair[1] + 2)):
                    smallest = pair[0]
                    count += 1
            return count

